<template>
  <AuthenticatedLayout page-title="Cotações e Compras">
    <div class="space-y-6"><TopCard title="Cotações e Compras" :icon="QuoteIcon"><template #actions><NeonButton @click="openCreate">Nova cotação</NeonButton></template></TopCard>
      <div v-if="error" class="rounded-lg border border-red-500/40 bg-red-500/10 p-4 text-red-100">{{ error }}</div>
      <div class="grid gap-4 lg:grid-cols-2"><article v-for="quotation in quotations" :key="quotation.id" class="rounded-lg border border-gray-700 bg-gray-900/70 p-5"><div class="flex justify-between"><div><p class="font-semibold text-white">{{ quotation.code }}</p><h2 class="mt-1 text-lg text-gray-100">{{ quotation.title }}</h2></div><span class="rounded-full bg-cyan-500/10 px-3 py-1 text-xs text-cyan-200">{{ labelStatus(quotation.status) }}</span></div><p class="mt-3 text-sm text-gray-400">Prazo: {{ quotation.response_deadline }}</p><div class="mt-5 flex gap-2"><NeonButton size="sm" variant="secondary" @click="show(quotation)">Detalhes</NeonButton><NeonButton v-if="quotation.status === 'draft'" size="sm" @click="publish(quotation)">Publicar</NeonButton></div></article></div>
      <div v-if="!quotations.length" class="rounded-lg border border-gray-700 bg-gray-900/60 py-16 text-center text-gray-400">Nenhuma cotação criada.</div>
    </div>
    <div v-if="modal" class="fixed inset-0 z-50 overflow-y-auto bg-black/70 p-4"><form class="mx-auto my-8 w-full max-w-2xl rounded-lg border border-cyan-500/30 bg-gray-900 p-6" @submit.prevent="create"><h2 class="text-xl font-semibold text-white">Nova cotação</h2><div class="mt-4 grid gap-3"><input v-model="form.title" class="input" placeholder="Título" required><textarea v-model="form.description" class="input" placeholder="Descrição"/><label class="text-sm text-gray-300">Prazo de resposta<input v-model="form.response_deadline" class="input mt-1" type="date" required></label><div v-for="(item, index) in form.items" :key="index" class="grid gap-2 rounded border border-gray-700 p-3 md:grid-cols-[1fr_100px_100px_auto]"><input v-model="item.description" class="input" placeholder="Item" required><input v-model="item.unit" class="input" placeholder="Unidade" required><input v-model.number="item.quantity" class="input" type="number" min="0.001" step="0.001" placeholder="Qtd." required><button type="button" class="text-sm text-red-300" @click="form.items.splice(index, 1)">Remover</button><textarea v-model="item.specification" class="input md:col-span-4" placeholder="Especificação"/></div><NeonButton type="button" size="sm" variant="secondary" @click="addItem">Adicionar item</NeonButton></div><div class="mt-6 flex justify-end gap-2"><NeonButton type="button" variant="secondary" @click="modal = false">Cancelar</NeonButton><NeonButton type="submit">Criar rascunho</NeonButton></div></form></div>
    <div v-if="detail" class="fixed inset-0 z-50 overflow-y-auto bg-black/70 p-4"><section class="mx-auto my-8 w-full max-w-4xl rounded-lg border border-cyan-500/30 bg-gray-900 p-6"><div class="flex justify-between"><div><p class="text-sm text-cyan-300">{{ detail.code }}</p><h2 class="text-xl font-semibold text-white">{{ detail.title }}</h2></div><button class="text-gray-400" @click="detail = null">Fechar</button></div><div class="mt-6 grid gap-4 lg:grid-cols-2"><section><h3 class="font-semibold text-white">Itens</h3><div v-for="item in detail.items" :key="item.id" class="mt-2 rounded border border-gray-700 p-3 text-sm text-gray-200">{{ item.quantity }} {{ item.unit }} - {{ item.description }}<p class="mt-1 text-gray-400">{{ item.specification }}</p></div></section><section><h3 class="font-semibold text-white">Convites</h3><div v-for="invite in detail.invitations" :key="invite.id" class="mt-2 rounded border border-gray-700 p-3"><p class="text-gray-200">{{ invite.supplier_name }}</p><p v-if="invite.response_url" class="break-all text-xs text-cyan-300">{{ invite.response_url }}</p></div><form class="mt-3 flex gap-2" @submit.prevent="invite"><input v-model="inviteForm.supplier_name" class="input" placeholder="Fornecedor" required><NeonButton type="submit" size="sm">Gerar link</NeonButton></form></section></div><form v-if="detail.status === 'published'" class="mt-6 rounded border border-gray-700 p-4" @submit.prevent="close"><h3 class="font-semibold text-white">Encerrar e registrar escolha</h3><div class="mt-3 grid gap-3 md:grid-cols-2"><select v-model="closing.criterion" class="input"><option value="lowest_total">Menor valor total</option><option value="lowest_item">Menor valor por item</option><option value="best_value">Melhor custo-benefício</option><option value="manual">Escolha manual</option></select><select v-if="closing.criterion !== 'lowest_item'" v-model="closing.quoteId" class="input"><option value="">Selecione a proposta vencedora</option><option v-for="invite in submittedInvitations" :key="invite.quote.id" :value="invite.quote.id">{{ invite.quote.supplier_name }} - {{ money(invite.quote.total) }}</option></select><div v-else class="md:col-span-2 space-y-2"><label v-for="item in detail.items" :key="item.id" class="grid gap-2 rounded border border-gray-700 p-3 text-sm text-gray-200 md:grid-cols-[1fr_1fr]"><span>{{ item.description }} ({{ item.quantity }} {{ item.unit }})</span><select v-model="closing.itemQuoteIds[item.id]" class="input"><option value="">Selecione a proposta deste item</option><option v-for="invite in quotesForItem(item.id)" :key="invite.quote.id" :value="invite.quote.id">{{ invite.quote.supplier_name }} - {{ quoteItemPrice(invite.quote, item.id) }}</option></select></label></div><textarea v-model="closing.justification" class="input md:col-span-2" placeholder="Justificativa da decisão"/></div><label class="mt-3 flex gap-2 text-sm text-gray-300"><input v-model="closing.publish_result" type="checkbox"> Publicar resultado para moradores</label><div class="mt-4 flex justify-end"><NeonButton type="submit">Encerrar cotação</NeonButton></div></form></section></div>
  </AuthenticatedLayout>
</template>

<script setup>
import { computed, h, onMounted, ref } from 'vue';
import api from '@/utils/api';
import AuthenticatedLayout from '../components/layouts/AuthenticatedLayout.vue';
import NeonButton from '../components/NeonButton.vue';
import TopCard from '../components/ui/TopCard.vue';
const quotations = ref([]); const error = ref(''); const modal = ref(false); const detail = ref(null); const inviteForm = ref({ supplier_name: '', supplier_email: '' }); const closing = ref({ criterion: 'lowest_total', quoteId: '', itemQuoteIds: {}, justification: '', publish_result: false }); const tomorrow = new Date(); tomorrow.setDate(tomorrow.getDate() + 7); const iso = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; const form = ref({ title: '', description: '', response_deadline: iso(tomorrow), items: [{ description: '', specification: '', unit: 'un', quantity: 1 }] });
const QuoteIcon = { render: () => h('span', { class: 'text-cyan-300' }, 'C$') }; const labelStatus = (status) => ({ draft: 'Rascunho', published: 'Aberta', closed: 'Encerrada' }[status] || status); const money = (value) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(value || 0)); const submittedInvitations = computed(() => (detail.value?.invitations || []).filter((invite) => invite.quote?.status === 'submitted'));
async function load() { try { quotations.value = (await api.get('/finance/procurements')).data; } catch { error.value = 'Não foi possível carregar as cotações.'; } }
function openCreate() { form.value = { title: '', description: '', response_deadline: iso(tomorrow), items: [{ description: '', specification: '', unit: 'un', quantity: 1 }] }; modal.value = true; }
function addItem() { form.value.items.push({ description: '', specification: '', unit: 'un', quantity: 1 }); }
async function create() { try { const { data } = await api.post('/finance/procurements', form.value); modal.value = false; await load(); await show(data); } catch (requestError) { error.value = requestError.response?.data?.message || 'Não foi possível criar a cotação.'; } }
function resetClosing() { closing.value = { criterion: 'lowest_total', quoteId: '', itemQuoteIds: {}, justification: '', publish_result: false }; }
function quotesForItem(itemId) { return submittedInvitations.value.filter((invite) => invite.quote.items?.some((item) => Number(item.procurement_item_id) === Number(itemId))); }
function quoteItemPrice(quote, itemId) { return money(quote.items?.find((item) => Number(item.procurement_item_id) === Number(itemId))?.unit_price); }
async function show(quotation) { try { detail.value = (await api.get(`/finance/procurements/${quotation.id}`)).data; resetClosing(); } catch { error.value = 'Não foi possível carregar os detalhes.'; } }
async function publish(quotation) { try { await api.post(`/finance/procurements/${quotation.id}/publish`); await load(); await show(quotation); } catch (requestError) { error.value = requestError.response?.data?.message || 'Não foi possível publicar.'; } }
async function invite() { try { const { data } = await api.post(`/finance/procurements/${detail.value.id}/invitations`, inviteForm.value); detail.value.invitations.push(data); inviteForm.value = { supplier_name: '', supplier_email: '' }; } catch (requestError) { error.value = requestError.response?.data?.message || 'Não foi possível criar o convite.'; } }
async function close() { try { const awards = closing.value.criterion === 'lowest_item' ? detail.value.items.map((item) => ({ procurement_item_id: item.id, supplier_quote_id: closing.value.itemQuoteIds[item.id] })) : [{ supplier_quote_id: closing.value.quoteId }]; if (awards.some((award) => !award.supplier_quote_id)) { error.value = 'Selecione uma proposta para cada item antes de encerrar.'; return; } await api.post(`/finance/procurements/${detail.value.id}/close`, { criterion: closing.value.criterion, justification: closing.value.justification, publish_result: closing.value.publish_result, awards }); await load(); await show(detail.value); } catch (requestError) { error.value = requestError.response?.data?.message || 'Não foi possível encerrar a cotação.'; } }
onMounted(load);
</script>
<style scoped>.input { width: 100%; border: 1px solid rgb(75 85 99); border-radius: .5rem; background: rgb(31 41 55); color: white; padding: .6rem .7rem; }</style>
